// ✅ LOADER (ОЧЕНЬ ВАЖНО)
export const loader = async () => {
  const customerId = "1";
  const wallet = await prisma.wallet.findFirst({
    where: {
      customerId
    }
  });
  const transactions = await prisma.pointsTransaction.findMany({
    where: {
      customerId
    },
    orderBy: {
      createdAt: "desc"
    },
    take: 20
  });
  return json({
    balance: wallet?.balance || 0,
    transactions
  });
};

